const b = $input.first().json;
const imageProviders = (b.providers && b.providers.image_gen) || [];
const provider = imageProviders.find((p) => p.enabled && p.provider === 'openai') || imageProviders[0] || { provider: 'openai', settings: {} };
const settings = provider.settings || {};
const size = settings.size || '1536x1024';
const quality = settings.quality || 'medium';
const model = settings.model || 'gpt-image-1';
return [{ json: {
  ctx: b, model, size, quality,
  requestBody: { model, prompt: b.generation_prompt || '', size, quality, n: 1 }
} }];

const resp = $input.first().json;
const { ctx } = $('Prepare OpenAI Request').first().json;
const statusCode = resp.statusCode || resp.status || (resp.error ? 400 : 0);
const retryable = statusCode === 0 || statusCode === 429 || statusCode >= 500;
return [{ json: {
  success: false, data: null,
  error: { code: 'VISUAL_ASSET_GENERATION_FAILED', message: 'OpenAI image generation call failed (status ' + statusCode + ')', retryable, error_id: null },
  runtime: { channel_id: ctx.channel_id }
} }];

const resp = $input.first().json;
const { ctx, model, size, quality } = $('Prepare OpenAI Request').first().json;
const item = resp.data[0];
const [w, h] = size.split('x').map((n) => parseInt(n, 10));
// Documented flat estimate per size/quality tier -- gpt-image-1 does not
// return per-call cost in its response. See
// docs/architecture/visual-asset-pipeline.md#generated-images.
const COST_BY_QUALITY = { low: 0.02, medium: 0.04, high: 0.19 };
const costUsd = COST_BY_QUALITY[quality] ?? 0.04;
return [{ json: {
  success: true,
  data: {
    provider: 'openai', model, request_id: resp.created ? ('req_' + resp.created) : null,
    width: w, height: h, prompt: ctx.generation_prompt || '', revised_prompt: item.revised_prompt || null,
    cost_usd: costUsd, metadata: { size, quality }, b64_data: item.b64_json,
  },
  error: null, runtime: { channel_id: ctx.channel_id },
} }];
